def move_picks(apps, schema_editor):
    """Each user already picked as a salesman or purchaser becomes a person on
    the new list, linked to the sign-in, ticked for the side they were picked on."""
    Ledger = apps.get_model("core", "Ledger")
    SalesPerson = apps.get_model("core", "SalesPerson")
    people = {}
    taken = {p.name.lower() for p in SalesPerson.objects.all()}
    for ledger in Ledger.objects.filter(salesman__isnull=False).select_related("salesman"):
        user = ledger.salesman
        person = people.get(user.pk)
        if person is None:
            name = (user.full_name or user.email).strip()[:100]
            if name.lower() in taken:
                name = f"{name} ({user.email})"[:100]
            taken.add(name.lower())
            person = SalesPerson.objects.create(
                name=name, email=user.email, user=user, is_active=user.is_active
            )
            people[user.pk] = person
        if ledger.party_side == "supplier":
            person.is_purchaser = True
        else:
            person.is_salesman = True
        person.save(update_fields=["is_salesman", "is_purchaser"])
        ledger.sales_person = person
        ledger.save(update_fields=["sales_person"])


